// ── GIST CONFIG ─────────────────────────────────────────────
const _r1='T9qcT2bOWy7pTjbEjE7d',_r2='dwfByajdWj0BmCNV_phg';
function _tok(){return(_r1+_r2).split('').reverse().join('');}

let _gistCache=null,_gistCacheTs=0;
async function loadFromGist(){
  const now=Date.now();
  if(_gistCache&&(now-_gistCacheTs)<30000) return _gistCache;
  try{
    const r=await fetch('https://api.github.com/gists/'+S.gistId,{
      headers:{'Authorization':'token '+_tok(),'Accept':'application/vnd.github.v3+json'}
    });
    const d=await r.json();
    function _parse(name,fb){
      try{return JSON.parse(d.files&&d.files[name]&&d.files[name].content||fb);}
      catch(e){return JSON.parse(fb);}
    }
    if(d.files&&d.files['calibrations.json']){
      // Formato novo: 3+ arquivos separados
      const analyses=_parse('analyses.json','{}');
      const calibs  =_parse('calibrations.json','{}');
      const wbs     =_parse('wbs.json','[]');
      const analyses_maio=_parse('analyses_maio.json','{}');
      const periods =_parse('periods.json','[]');
      const agents  =_parse('agents.json','[]');
      const merged  =Object.assign({},analyses,calibs);
      merged[WBS_KEY]=Array.isArray(wbs)?wbs:[];
      merged['__maio__']=analyses_maio;
      merged['__periods__']=Array.isArray(periods)?periods:[];
      merged['__agents__']=Array.isArray(agents)?agents:[];
      // Carregar análises de períodos dinâmicos
      const dynAnalyses={};
      for(const p of merged['__periods__']){
        const fname='analyses_'+p.id+'.json';
        if(d.files&&d.files[fname]) try{dynAnalyses[p.id]=JSON.parse(d.files[fname].content||'{}');}catch{dynAnalyses[p.id]={};}
        else dynAnalyses[p.id]={};
      }
      merged['__dyn__']=dynAnalyses;
      _gistCache=merged;_gistCacheTs=now;
      return merged;
    }else{
      // Formato legado: arquivo único
      const content=d.files&&d.files['analyses.json']&&d.files['analyses.json'].content;
      if(content){_gistCache=JSON.parse(content);_gistCacheTs=now;return _gistCache;}
    }
  }catch(e){console.warn('Gist load:',e);}
  return _gistCache||null;
}

// ── DEBOUNCE SAVE ────────────────────────────────────────────
let _saveTimer=null,_pendingSave=null;
function debouncedSave(){
  if(_saveTimer) clearTimeout(_saveTimer);
  _saveTimer=setTimeout(function(){saveAnalysesToGist();_saveTimer=null;},1500);
}

async function _patchGist(files){
  try{
    const res=await fetch('https://api.github.com/gists/'+S.gistId,{
      method:'PATCH',
      headers:{'Authorization':'token '+_tok(),'Content-Type':'application/json','Accept':'application/vnd.github.v3+json'},
      body:JSON.stringify({files:files})
    });
    if(!res.ok){
      const msg=await res.text().catch(()=>res.status);
      console.error('Gist patch failed:',res.status,msg);
      toast('⚠️ Erro ao salvar no servidor ('+res.status+'). Dados salvos localmente.');
      return false;
    }
    _gistCacheTs=0;return true;
  }catch(e){console.warn('Gist patch:',e);toast('⚠️ Sem conexão — dado salvo localmente.');return false;}
}
function _onlyTickets(){const o={};Object.entries(S.analyses).forEach(function(e){if(!e[0].startsWith('_'))o[e[0]]=e[1];});return o;}
function _onlyCalib(){const o={};Object.entries(S.analyses).forEach(function(e){if(e[0].startsWith('_cal_'))o[e[0]]=e[1];});return o;}
async function saveAnalysesToGist(){
  if(!S.gistId)return;
  try{
    const r=await fetch('https://api.github.com/gists/'+S.gistId,{headers:{'Authorization':'token '+_tok(),'Accept':'application/vnd.github.v3+json'}});
    if(r.ok){const g=await r.json();const remote=JSON.parse(g.files['analyses.json'].content||'{}');Object.assign(remote,_onlyTickets());return _patchGist({'analyses.json':{content:JSON.stringify(remote)}});}
  }catch(e){console.warn('merge fetch:',e);}
  return _patchGist({'analyses.json':{content:JSON.stringify(_onlyTickets())}});
}
async function saveCalibrationsToGist(){if(!S.gistId)return;return _patchGist({'calibrations.json':{content:JSON.stringify(_onlyCalib())}});}
async function saveWBSToGist(){if(!S.gistId)return;const wbs=S.analyses[WBS_KEY]||[];return _patchGist({'wbs.json':{content:JSON.stringify(wbs,null,2)}});}
async function saveToGist(data){return saveAnalysesToGist();}
async function saveMaioAnalysesToGist(){
  if(!S.gistId)return;
  try{
    const r=await fetch('https://api.github.com/gists/'+S.gistId,{headers:{'Authorization':'token '+_tok(),'Accept':'application/vnd.github.v3+json'}});
    if(r.ok){const g=await r.json();const remote=JSON.parse(g.files['analyses_maio.json'].content||'{}');Object.assign(remote,S.analyses_maio);S.analyses_maio=remote;}
  }catch(e){console.warn('merge fetch:',e);}
  return _patchGist({'analyses_maio.json':{content:JSON.stringify(S.analyses_maio)}});
}

// ── PERIOD HELPERS ────────────────────────────────────────────
function isDynPeriod(p){return p&&p!=='fevapr'&&p!=='maio';}
function getDynPeriod(id){return S.dynamic_periods.find(p=>p.id===id)||null;}
function curTickets(){
  if(S.period==='maio') return TICKETS_MAIO;
  if(isDynPeriod(S.period)){const dp=getDynPeriod(S.period);return dp?dp.tickets:{};}
  return TICKETS;
}
function curAllIds(){
  if(S.period==='maio') return ALL_IDS_MAIO;
  if(isDynPeriod(S.period)){const dp=getDynPeriod(S.period);if(!dp)return[];return Object.values(dp.tickets).flat().map(t=>t[0]);}
  return ALL_IDS;
}
function curAnalyses(){
  if(S.period==='maio') return S.analyses_maio;
  if(isDynPeriod(S.period)){if(!S.dynamic_analyses[S.period])S.dynamic_analyses[S.period]={};return S.dynamic_analyses[S.period];}
  return S.analyses;
}
function setAnalysis(id,data){
  if(S.period==='maio') S.analyses_maio[id]=data;
  else if(isDynPeriod(S.period)){if(!S.dynamic_analyses[S.period])S.dynamic_analyses[S.period]={};S.dynamic_analyses[S.period][id]=data;}
  else S.analyses[id]=data;
}
async function saveDynAnalysesToGist(periodId){
  if(!S.gistId)return;
  const fname='analyses_'+periodId+'.json';
  const data=S.dynamic_analyses[periodId]||{};
  return _patchGist({[fname]:{content:JSON.stringify(data)}});
}
async function savePeriodsToGist(){
  if(!S.gistId)return;
  return _patchGist({'periods.json':{content:JSON.stringify(S.dynamic_periods,null,2)}});
}
async function saveAgentsToGist(){
  if(!S.gistId)return;
  return _patchGist({'agents.json':{content:JSON.stringify(S.custom_agents,null,2)}});
}
function debouncedSavePeriod(){
  if(S.period==='maio'){if(_saveTimer)clearTimeout(_saveTimer);_saveTimer=setTimeout(function(){saveMaioAnalysesToGist();_saveTimer=null;},1500);}
  else if(isDynPeriod(S.period)){const pid=S.period;if(_saveTimer)clearTimeout(_saveTimer);_saveTimer=setTimeout(function(){saveDynAnalysesToGist(pid);_saveTimer=null;},1500);}
  else{debouncedSave();}
}

// ── INIT ──────────────────────────────────────────────────────
async function init(){
  const gistData=await loadFromGist();
  if(gistData){
    S.analyses_maio=gistData['__maio__']||{};
    S.dynamic_periods=gistData['__periods__']||[];
    S.dynamic_analyses=gistData['__dyn__']||{};
    S.custom_agents=gistData['__agents__']||[];
    delete gistData['__maio__'];delete gistData['__periods__'];delete gistData['__dyn__'];delete gistData['__agents__'];
    S.analyses=gistData;
    cacheAnalyses();
  }else{
    const cached=getCachedAnalyses();
    S.analyses=cached.fevapr||cached;
    S.analyses_maio=cached.maio||{};
  }
  renderAgentPills();
  updateProgress();
  setScreen('home');
  updateAuthUI();
  // Sync remoto a cada 60s para pegar dados de outros agentes
  setInterval(async function(){
    if(S.saving)return;
    const fresh=await loadFromGist();
    if(!fresh)return;
    const maio=fresh['__maio__']||{};
    const periods=fresh['__periods__']||[];
    const dynAnls=fresh['__dyn__']||{};
    const remoteAgents=fresh['__agents__']||[];
    delete fresh['__maio__'];delete fresh['__periods__'];delete fresh['__dyn__'];delete fresh['__agents__'];
    // Merge remoto no local (remoto vence para chaves não editadas nesta sessão)
    let changed=false;
    Object.entries(fresh).forEach(function([k,v]){if(!S.analyses[k]){S.analyses[k]=v;changed=true;}});
    Object.entries(maio).forEach(function([k,v]){if(!S.analyses_maio[k]){S.analyses_maio[k]=v;changed=true;}});
    // Atualiza períodos dinâmicos se mudou remotamente
    if(periods.length!==S.dynamic_periods.length){S.dynamic_periods=periods;changed=true;}
    if(remoteAgents.length!==S.custom_agents.length){S.custom_agents=remoteAgents;changed=true;}
    Object.entries(dynAnls).forEach(function([pid,anls]){
      if(!S.dynamic_analyses[pid])S.dynamic_analyses[pid]={};
      Object.entries(anls).forEach(function([k,v]){if(!S.dynamic_analyses[pid][k]){S.dynamic_analyses[pid][k]=v;changed=true;}});
    });
    if(changed){cacheAnalyses();updateProgress();renderAgentPills();if(S.screen==='analyze'){if(document.getElementById('sb-items'))_renderSbItems();else renderSidebar();}}
  },60000);
}

function getCachedAnalyses(){
  try{const c=JSON.parse(localStorage.getItem('enotas_cache')||'{}');return c;}catch{return{};}
}
function cacheAnalyses(){localStorage.setItem('enotas_cache',JSON.stringify({fevapr:S.analyses,maio:S.analyses_maio}));}

// ── SAVE ──────────────────────────────────────────────────────
async function saveAnalysis(goNext=true){
  if(!_auth){requireAuth(function(){saveAnalysis(goNext);});return;}
  const tkt=curTickets()[S.agent][S.idx];
  const data={...S.form,ticketId:tkt[0],agent:S.agent,tema:tkt[1],categoria:tkt[2],period:S.period,savedAt:new Date().toISOString()};
  setAnalysis(tkt[0],data);
  cacheAnalyses();
  updateProgress();
  if(document.getElementById('sb-items'))_renderSbItems();else renderSidebar();
  renderAgentPills();

  if(S.gistId){
    cacheAnalyses();debouncedSavePeriod();
  }
  S._formDirty=false;
  toast('Salvo ✓');

  if(goNext&&S.idx<curTickets()[S.agent].length-1){
    S.idx++;
    S.form=curAnalyses()[curTickets()[S.agent][S.idx][0]]||{};
    renderAnalyze();
    if(document.getElementById('sb-items'))_renderSbItems();else renderSidebar();
    scrollSidebar();
  }
}

// ── SCREENS ───────────────────────────────────────────────────
function setScreen(name){
  S.screen=name;
  ['loading','home','analyze','export','calibration','wbs','admin'].forEach(s=>{
    const flexScreens=['wbs','admin'];
    document.getElementById('screen-'+s).style.display=s===name?(flexScreens.includes(s)?'flex':''):'none';
  });
  const cl=document.getElementById('cal-layout');
  if(cl) cl.style.display='none';
  const ml=document.getElementById('main-layout');
  if(ml) ml.style.display='flex';
  const bb=document.getElementById('back-btn');
  const bsep=document.getElementById('back-sep');
  if(bb){const show=(name==='analyze'||name==='export'||name==='calibration'||name==='admin');bb.style.display=show?'flex':'none';if(bsep)bsep.style.display=show?'block':'none';if(name==='calibration'){bb.textContent='← Análise';bb.onclick=()=>{S.screen=S.agent?'analyze':'home';setScreen(S.agent?'analyze':'home');renderAgentPills();}}else if(name==='analyze'&&S.agent){bb.textContent='← Avaliadores';bb.onclick=()=>{S.agent=null;renderAgentPicker(S.period);};}else{bb.textContent='← Início';bb.onclick=()=>setScreen('home');}}
  const sb=document.getElementById('sidebar');
  if(sb) sb.style.display=(name==='analyze'||name==='export'||name==='calibration')?'flex':'none';
  if(name==='wbs'&&sb) sb.style.display='none';
  if(name==='home'){
    S.agent=null;S.period=null;
    updateHeaderSub();
    document.getElementById('sb-list').innerHTML='<div style="color:rgba(0,0,0,.3);font-size:12px;padding:16px 8px;text-align:center">Selecione um agente</div>';
    renderAgentPills();
    updateProgress();
    renderHome();
  }
  if(name==='analyze')renderAnalyze();
  if(name==='export')renderExport();
  if(name==='wbs')renderWBS();
  if(name==='admin')renderAdmin();
  updateAuthUI();
}
function agentDone(a){return curTickets()[a].filter(t=>curAnalyses()[t[0]]).length;}
function agentTotal(a){return curTickets()[a].length;}
function agentPct(a){return Math.round(agentDone(a)/agentTotal(a)*100);}
function agentDoneFevapr(a){return TICKETS[a].filter(t=>S.analyses[t[0]]).length;}
function agentDoneMaio(a){return TICKETS_MAIO[a].filter(t=>S.analyses_maio[t[0]]).length;}
function totalDone(){
  if(S.period==='maio') return ALL_IDS_MAIO.filter(id=>S.analyses_maio[id]).length;
  return ALL_IDS.filter(id=>S.analyses[id]&&!String(id).startsWith("_cal_")).length;
}

function updateHeaderSub(){
  const el=document.getElementById('hdr-sub');
  if(!el)return;
  if(!S.period){el.textContent='';return;}
  if(S.period==='fevapr') el.textContent='Tickets N1/N2 · Fev–Abr 2026';
  else if(S.period==='maio') el.textContent='Tickets N1/N2 · Maio 2026';
  else{const dp=getDynPeriod(S.period);el.textContent=dp?'Tickets N1/N2 · '+dp.label:'';}
}

function updateProgress(){
  const el=document.getElementById('hdr-progress');
  if(!el)return;
  // Totais dinâmicos
  const dynDone=S.dynamic_periods.reduce(function(acc,dp){
    const tks=Object.values(dp.tickets||{}).flat();
    const anls=S.dynamic_analyses[dp.id]||{};
    return acc+tks.filter(function(t){return anls[t[0]];}).length;
  },0);
  const dynTotal=S.dynamic_periods.reduce(function(acc,dp){return acc+Object.values(dp.tickets||{}).flat().length;},0);
  if(S.agent&&S.period==='maio'){
    const d=ALL_IDS_MAIO.filter(id=>S.analyses_maio[id]).length;
    el.textContent=d+' / '+ALL_IDS_MAIO.length+' · Maio';
  }else if(S.agent&&isDynPeriod(S.period)){
    const dp=getDynPeriod(S.period);
    const tks=dp?Object.values(dp.tickets||{}).flat():[];
    const anls=S.dynamic_analyses[S.period]||{};
    const d=tks.filter(function(t){return anls[t[0]];}).length;
    el.textContent=d+' / '+tks.length+' · '+(dp?dp.label:'');
  }else if(S.agent&&S.period==='fevapr'){
    const d=ALL_IDS.filter(id=>S.analyses[id]&&!String(id).startsWith('_cal_')).length;
    el.textContent=d+' / '+ALL_IDS.length+' · Fev-Abr';
  }else{
    const dF=ALL_IDS.filter(id=>S.analyses[id]&&!String(id).startsWith('_cal_')).length;
    const dM=ALL_IDS_MAIO.filter(id=>S.analyses_maio[id]).length;
    el.textContent=(dF+dM+dynDone)+' / '+(ALL_IDS.length+ALL_IDS_MAIO.length+dynTotal);
  }
}

