function _renderXLSXModal(){
  // períodos
  const periods=[['all','Todos os períodos'],['fevapr','Fev — Abr'],['maio','Maio']].concat(
    S.dynamic_periods.map(function(dp){return[dp.id,dp.label];}));
  document.getElementById('xlsx-period-opts').innerHTML=periods.map(function(p){
    const act=_xlsxOpts.period===p[0];
    return`<button onclick="_xlsxOpts.period='${p[0]}';_xlsxOpts.agent='all';_renderXLSXModal()" style="padding:4px 12px;border-radius:16px;font-size:12px;font-weight:600;cursor:pointer;border:1.5px solid;font-family:inherit;transition:.12s;${act?'background:var(--primary);color:#fff;border-color:var(--primary)':'background:transparent;color:var(--primary-dark);border-color:var(--border2)'}">${escHtml(p[1])}</button>`;
  }).join('');

  // agentes (depende do período)
  let agentList=['all'];
  if(_xlsxOpts.period==='fevapr'||_xlsxOpts.period==='all') agentList=agentList.concat(AGENTS);
  else if(_xlsxOpts.period==='maio') agentList=agentList.concat(AGENTS);
  else{const dp=getDynPeriod(_xlsxOpts.period);if(dp&&dp.agents)agentList=agentList.concat(dp.agents);}
  // deduplica
  agentList=agentList.filter(function(v,i,a){return a.indexOf(v)===i;});
  document.getElementById('xlsx-agent-opts').innerHTML=agentList.map(function(a){
    const act=_xlsxOpts.agent===a;
    const col=a==='all'?'var(--primary)':agentColor(a);
    const label=a==='all'?'Todos':a;
    return`<button onclick="_xlsxOpts.agent='${a}';_renderXLSXModal()" style="padding:4px 12px;border-radius:16px;font-size:12px;font-weight:600;cursor:pointer;border:1.5px solid;font-family:inherit;transition:.12s;${act?'background:'+col+';color:#fff;border-color:'+col:'background:transparent;color:'+col+';border-color:'+col+'66'}">${escHtml(label)}</button>`;
  }).join('');
}

