function renderCalSidebar(){
  if(!SC.agent)return;
  const cal=curCalibration()[SC.agent];
  const el=document.getElementById('cal-sb-content');
  if(!el)return;
  const total=calTotal();
  const done=calDone(SC.agent);
  const allDone=done===total;
  let h='<div style="padding:6px">';
  h+='<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--primary-dark);padding:8px 6px 4px;cursor:pointer" onclick="SC.agent=null;renderCalAgents()">← Revisores</div>';
  h+='<div style="font-size:11px;font-weight:700;color:var(--primary-dark);padding:4px 6px 8px;border-bottom:1px solid var(--border);margin-bottom:6px">'+SC.agent+' revisa '+cal.orig+'</div>';
  const calSrc=curCalAnalyses();
  cal.tickets.forEach(function(tid,i){
    const isDone=!!calSrc[curCalKey(SC.agent,tid)],active=i===SC.idx;
    const bg=active?'background:var(--primary-light);border-left:3px solid var(--primary);':'';
    const dotCls=active?'d-active':isDone?(SC.agent==='Rapha'?'d-done-rapha':SC.agent==='Calais'?'d-done-calais':'d-done-ale'):'d-pending';
    h+='<div class="cal-tkt-btn" data-calidx="'+i+'" style="display:flex;align-items:center;gap:6px;padding:6px 8px;border-radius:5px;cursor:pointer;margin-bottom:2px;'+bg+'">';
    h+='<div class="sb-dot '+dotCls+'" style="pointer-events:none"></div>';
    h+='<span class="sb-id" style="pointer-events:none">'+tid+'</span>';
    if(isDone)h+='<span style="font-size:10px;color:var(--green);pointer-events:none">✓</span>';
    h+='</div>';
  });
  // Botão de média de concordância (só aparece quando todas 10 estão feitas)
  if(allDone){
    const avg=agentCalConcordance(SC.agent);
    const color=avg>=80?'var(--green)':avg>=60?'var(--yellow)':'var(--red)';
    h+='<div style="margin-top:10px;padding:10px 8px;background:var(--surface2);border-radius:8px;border:1px solid var(--border2)">';
    h+='<div style="font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text2);margin-bottom:6px">Média de Concordância</div>';
    h+='<div style="font-family:Nunito,sans-serif;font-size:26px;font-weight:700;color:'+color+'">'+avg+'%</div>';
    h+='<div style="font-size:11px;color:var(--text2);margin-top:2px">'+SC.agent+' vs '+cal.orig+'</div>';
    h+='<div style="height:6px;background:var(--border);border-radius:4px;margin-top:8px;overflow:hidden"><div style="width:'+avg+'%;height:100%;background:'+color+';border-radius:4px;transition:width .5s"></div></div>';
    h+='</div>';
  } else {
    h+='<div style="margin-top:10px;padding:8px;background:var(--surface2);border-radius:8px;border:1px dashed var(--border2);text-align:center">';
    h+='<div style="font-size:11px;color:var(--text3)">'+done+'/'+total+' revisados</div>';
    h+='<div style="font-size:10px;color:var(--text3);margin-top:2px">Conclua todos para ver a média</div>';
    h+='</div>';
  }
  h+='</div>';
  el.innerHTML=h;
  el.onclick=function(e){
    const tkt=e.target.closest('.cal-tkt-btn');
    if(tkt) jumpCal(parseInt(tkt.dataset.calidx));
  };
}
